397	// writeLegacyV1File 用当前状态构造一个去掉 sources/corrections 字段、并
398	// 把路标历次出现压回旧版平铺字段的旧版文件（二进制版本号仍为 1），模拟
399	// 现网旧地图。
400	func writeLegacyV1File(t *testing.T, path string, st *mapState) {
401		t.Helper()
402		data, err := encodeFile(st)
403		if err != nil {
404			t.Fatal(err)
405		}
406		var raw map[string]any
407		if err := json.Unmarshal(data[headerLen:len(data)-4], &raw); err != nil {
408			t.Fatal(err)
409		}
410		delete(raw, "sources")
411		delete(raw, "corrections")
412		if lms, ok := raw["landmarks"].([]any); ok {
413			for _, e := range lms {
414				lm, ok := e.(map[string]any)
415				if !ok {
416					continue
417				}
418				occs, ok := lm["occurrences"].([]any)
419				if !ok || len(occs) == 0 {
420					continue
421				}
422				first, _ := occs[0].(map[string]any)
423				lm["x"] = first["x"]
424				lm["y"] = first["y"]
425				lm["count"] = first["count"]
426				delete(lm, "occurrences")
427			}
428		}
429		payload, err := json.Marshal(raw)
430		if err != nil {
431			t.Fatal(err)
432		}
433		out := make([]byte, headerLen+len(payload)+4)
434		copy(out[:headerLen], data[:headerLen])
435		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
436		copy(out[headerLen:], payload)
437		binary.BigEndian.PutUint32(out[len(out)-4:], crc32.ChecksumIEEE(out[:len(out)-4]))
438		if err := os.WriteFile(path, out, 0o644); err != nil {
439			t.Fatal(err)
440		}
441	}
