456		}
457		writeLegacyV1File(t, path, m.state)
458		if err := m.Close(); err != nil {
459			t.Fatal(err)
460		}
461	
462		m2, err := Open(path)
463		if err != nil {
464			t.Fatalf("open legacy: %v", err)
465		}
466		defer m2.Close()
467	
468		// 旧文件可正常打开、查询。
469		p, err := m2.PoseAt(100)
