487		// 旧地图上可继续导入：t=300 位姿 (2.5,0)，K 观测 (2.5,0) 距旧均值
488		// (1.5,0) 恰为合并距离，接受；K 均值变为 5.5/3，次数 3。
489		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
