248				_, err := m.ImportSegment(c.seg)
249				if err == nil {
250					t.Fatal("expected rejection")
251				}
252				if c.frame >= 0 {
253					rejectKind(t, err, c.kind, c.frame, c.landmark)
254				} else {
255					r, ok := AsRejectError(err)
256					if !ok || r.Kind != c.kind {
257						t.Fatalf("kind = %v, want %s", err, c.kind)
258					}
259				}
260			})
261		}
